{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Metoclopramide, a structurally related dimethoxybenzamide with an aromatic amine and basic amide side chain, has approximately 77% oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Donepezil, a dimethoxy-substituted aromatic drug with a basic piperidine, has an absolute oral bioavailability of 100% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Suvorexant, a heteroaromatic drug with amide and azole functionalities, has a mean oral bioavailability of 82% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Delavirdine, a piperazine-containing heteroaromatic drug, has an oral bioavailability of 85% in patients with HIV infection, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Piritrexim, a lipophilic dimethoxy-substituted aromatic antifolate, has an estimated oral bioavailability of approximately 75%, with absolute values mostly 40-75%, all at or above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show oral bioavailability well above 20% (mostly 46-100%), and the query's physicochemical properties are favorable; therefore predict high oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule itself.",
    "First-pass metabolism and transporter effects for the query are not directly assessed.",
    "Some analogue bioavailability values are variable, but all remain at or above the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

